CREATE TABLE employees(id INTEGER PRIMARY KEY, name TEXT, salary INTEGER);
CREATE TABLE audit_log(action TEXT, emp_id INTEGER, emp_name TEXT);
CREATE TRIGGER after_employee_insert AFTER INSERT ON employees
BEGIN
  INSERT INTO audit_log VALUES('INSERT', NEW.id, NEW.name);
END;
INSERT INTO employees VALUES(1, 'Alice', 50000);
INSERT INTO employees VALUES(2, 'Bob', 60000);
SELECT * FROM employees;
SELECT action, emp_id, emp_name FROM audit_log;

CREATE TABLE products(id INTEGER PRIMARY KEY, name TEXT, price REAL, last_updated TEXT);
CREATE TRIGGER before_product_update BEFORE UPDATE ON products
BEGIN
  UPDATE products SET last_updated = datetime('now') WHERE id = OLD.id;
END;
INSERT INTO products VALUES(1, 'Widget', 10.00, NULL);
UPDATE products SET price = 15.00 WHERE id = 1;
SELECT id, name, price FROM products;

CREATE TABLE accounts(id INTEGER PRIMARY KEY, name TEXT, balance REAL);
CREATE TABLE deleted_accounts(id INTEGER, name TEXT, balance REAL, deleted_at TEXT);
CREATE TRIGGER after_account_delete AFTER DELETE ON accounts
BEGIN
  INSERT INTO deleted_accounts VALUES(OLD.id, OLD.name, OLD.balance, 'deleted');
END;
INSERT INTO accounts VALUES(1, 'John', 1000.00);
INSERT INTO accounts VALUES(2, 'Jane', 2000.00);
DELETE FROM accounts WHERE id = 1;
SELECT * FROM accounts;
SELECT id, name, balance FROM deleted_accounts;

