CREATE TABLE base(id INTEGER PRIMARY KEY, value TEXT);
CREATE VIEW base_view AS SELECT id, value FROM base;
CREATE TRIGGER view_update INSTEAD OF UPDATE ON base_view
BEGIN
  UPDATE base SET value = NEW.value || '_updated' WHERE id = OLD.id;
END;
INSERT INTO base VALUES(1, 'original');
UPDATE base_view SET value = 'modified' WHERE id = 1;
