CREATE TRIGGER view_delete INSTEAD OF DELETE ON active_records
BEGIN
  UPDATE records SET deleted = 1 WHERE id = OLD.id;
END;
INSERT INTO records(id, data) VALUES(1, 'Record 1');
INSERT INTO records(id, data) VALUES(2, 'Record 2');
DELETE FROM active_records WHERE id = 1;
SELECT * FROM records;
